-- Set programs that you use
local terminal = "kitty"
local fileManager = "nautilus"
local menu = "wofi"

-- Cursor theme/size. "Adwaita-Tiny" is a local theme (~/.icons) generated to
-- contain the nominal sizes 1-24 px. The stock Adwaita theme only ships
-- 24/30/36/48/72/96, and Xcursor never scales *down* below a theme's smallest
-- bitmap - so any value below 24 (e.g. 1) silently rendered as 24 px.
local cursorTheme = "Adwaita-Tiny"
-- Any nominal size 1-24 now renders exactly as written. 16 is small but
-- clearly visible; 1 is a single pixel (effectively invisible) - avoid it.
local cursorSize = "16"

