-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function()
	--   hl.exec_cmd(terminal)
	--   hl.exec_cmd("nm-applet")
	hl.exec_cmd("swaybg -m fill -i /home/pdev/wallpaper/jonatan-pie-h8nxGssjQXs-unsplash.jpg")
	hl.exec_cmd("clipse -listen")
	hl.exec_cmd("waybar")
	hl.exec_cmd("/home/pdev/.config/waybar/scripts/ws-sync.sh")
	hl.exec_cmd("/home/pdev/.config/waybar/scripts/audio-watch.sh")
	-- One wl-paste watcher for the "Copied to clipboard" toast.
	hl.exec_cmd("/home/pdev/.config/hypr/scripts/clipboard-toast.sh")
	-- hypridle is optional: start it only once the package is installed.
	hl.exec_cmd("command -v hypridle >/dev/null 2>&1 && hypridle")
	-- Polkit agent for GUI authentication prompts (package: hyprpolkitagent).
	hl.exec_cmd("command -v hyprpolkitagent >/dev/null 2>&1 && exec hyprpolkitagent; [ -x /usr/lib/hyprpolkitagent/hyprpolkitagent ] && exec /usr/lib/hyprpolkitagent/hyprpolkitagent")
	-- Apply the cursor theme/size to the compositor itself (the XCURSOR_* env
	-- vars alone are not reliably picked up for the compositor at startup).
	hl.exec_cmd("hyprctl setcursor " .. cursorTheme .. " " .. cursorSize)
end)

-- Waybar workspace sync (no polling).
-- hyprland/workspaces cannot work on 0.56: it still sends the legacy
-- "dispatch workspace N" IPC string, and 0.56 parses dispatch as Lua, so the
-- click fails with a parse error. The bar therefore uses custom/ws1..ws10,
-- which dispatch hl.dsp.focus() correctly. ws-sync.sh takes one hyprctl
-- snapshot, caches it and pings the modules with SIGRTMIN+8.
local function sync_waybar_workspaces()
	hl.exec_cmd("/home/pdev/.config/waybar/scripts/ws-sync.sh")
end
hl.on("workspace.active", sync_waybar_workspaces)
hl.on("workspace.created", sync_waybar_workspaces)
hl.on("workspace.removed", sync_waybar_workspaces)
hl.on("window.open", sync_waybar_workspaces)
hl.on("window.close", sync_waybar_workspaces)

