-- Ctrl + mouse wheel: font size in the active terminal.
-- kitty's mouse_map only accepts mouse buttons (not scroll), so translate the
-- wheel into each terminal's keyboard zoom shortcut at the compositor level.
-- The active-window guard keeps Ctrl+wheel untouched in other applications.
local function terminal_font_zoom(key)
	local win = hl.get_active_window()
	if not win then
		return
	end

	local cls = win.class or ""
	local mods
	if cls == "kitty" then
		mods = "CTRL SHIFT" -- kitty: kitty_mod+equal / kitty_mod+minus
	elseif cls == "com.mitchellh.ghostty" then
		mods = "CTRL" -- ghostty: ctrl+equal / ctrl+minus
	else
		return
	end

	-- Send an explicit down/up pair; a lone press would leave the key held.
	hl.dispatch(hl.dsp.send_key_state({
		mods = mods,
		key = key,
		state = "down",
		window = win,
	}))

	return hl.dispatch(hl.dsp.send_key_state({
		mods = mods,
		key = key,
		state = "up",
		window = win,
	}))
end

hl.bind("CTRL + mouse_up", function()
	return terminal_font_zoom("equal")
end, { auto_consuming = true, description = "Terminal: zoom in" })

hl.bind("CTRL + mouse_down", function()
	return terminal_font_zoom("minus")
end, { auto_consuming = true, description = "Terminal: zoom out" })
